-- One row per value of each Keyword List attribute of each execution, kept by the trigger below.
-- The key holds a SHA-256 of the value (as NVARCHAR), so a value of any length is indexed.
CREATE TABLE executions_visibility_keyword_lists (
  namespace_id      CHAR(64)     NOT NULL,
  run_id            CHAR(64)     NOT NULL,
  search_attribute  VARCHAR(64)  NOT NULL,
  value_hash        BINARY(32)   NOT NULL,
  PRIMARY KEY (namespace_id, run_id, search_attribute, value_hash)
);

CREATE INDEX by_keyword_list_value ON executions_visibility_keyword_lists (namespace_id, search_attribute, value_hash, run_id);

CREATE TRIGGER executions_visibility_keyword_lists_sync ON executions_visibility
AFTER INSERT, UPDATE, DELETE AS
BEGIN
  SET NOCOUNT ON;
  DELETE kl FROM executions_visibility_keyword_lists kl
    INNER JOIN deleted d ON kl.namespace_id = d.namespace_id AND kl.run_id = d.run_id;
  INSERT INTO executions_visibility_keyword_lists (namespace_id, run_id, search_attribute, value_hash)
    SELECT DISTINCT i.namespace_id, i.run_id, CAST(a.[key] AS VARCHAR(64)), CAST(HASHBYTES('SHA2_256', v.value) AS BINARY(32))
    FROM inserted i
    CROSS APPLY OPENJSON(i.search_attributes) a
    CROSS APPLY OPENJSON(IIF(a.type = 4, a.value, N'[]')) v
    WHERE i.search_attributes IS NOT NULL AND a.type = 4 AND v.type = 1;
END;
